function timeAgo(dateStr) {
    const seconds = Math.floor((Date.now() - new Date(dateStr).getTime()) / 1000);
    const intervals = [
        {
            label: 'y',
            seconds: 31536000
        },
        {
            label: 'mo',
            seconds: 2592000
        },
        {
            label: 'd',
            seconds: 86400
        },
        {
            label: 'h',
            seconds: 3600
        },
        {
            label: 'm',
            seconds: 60
        }
    ];
    for (const { label, seconds: s } of intervals){
        const count = Math.floor(seconds / s);
        if (count >= 1) return `${count}${label} ago`;
    }
    return 'just now';
}
